codeExamples.code:
# 1) Health check on the primary region endpoint
aws route53 create-health-check --caller-reference hc-primary-1 \
  --health-check-config '{
    "Type":"HTTPS","FullyQualifiedDomainName":"api-primary.example.com",
    "Port":443,"ResourcePath":"/health",
    "RequestInterval":30,"FailureThreshold":3
  }'

# 2) Failover record set: PRIMARY (with health check) + SECONDARY
cat > records.json <<'EOF'
{
  "Changes":[
    { "Action":"UPSERT","ResourceRecordSet":{
        "Name":"api.example.com","Type":"A","SetIdentifier":"primary",
        "Failover":"PRIMARY","HealthCheckId":"HC_PRIMARY_ID",
        "AliasTarget":{"HostedZoneId":"Z_ALB_PRIMARY","DNSName":"alb-primary.example.com","EvaluateTargetHealth":true}
    }},
    { "Action":"UPSERT","ResourceRecordSet":{
        "Name":"api.example.com","Type":"A","SetIdentifier":"secondary",
        "Failover":"SECONDARY",
        "AliasTarget":{"HostedZoneId":"Z_ALB_DR","DNSName":"alb-dr.example.com","EvaluateTargetHealth":true}
    }}
  ]
}
EOF

aws route53 change-resource-record-sets \
  --hosted-zone-id Z_HOSTED_ZONE \
  --change-batch file://records.json
